#!/usr/bin/env node
// Look up an item in the case system:  case <ID> [--json]
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { inflateSync } from "node:zlib";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const args = process.argv.slice(2);
const ids = args.filter((a) => !a.startsWith("-"));
if (ids.length !== 1) {
  console.error("usage: case <ID> [--json]");
  process.exit(2);
}

function load() {
  const buf = readFileSync(join(root, ".cases/store.dat"));
  if (buf.subarray(0, 4).toString("latin1") !== "WLC1") throw new Error("case: unreadable store");
  return JSON.parse(inflateSync(buf.subarray(4)).toString("utf8"));
}

